new = '''    def _clean_up(self):
        "Complete the client lifecycle for context exit."
        self.flush(terminate=True)

        config_thread = getattr(self, "_config_thread", None)
        if config_thread is not None and config_thread.is_alive():
            config_thread.join()

        for thread in self._consumer_threads:
            if thread.is_alive():
                thread.join()

        if self._atexit_callback_registered:
            atexit.unregister(self._at_exit_callback)
            self._atexit_callback_registered = False

        if get_telemetry_client() is self:
            _set_telemetry_client(None)
